 "content": "def transform(grid):
    divider = next(i for i, row in enumerate(grid) if row and all(v == 5 for v in row))
    counts = {}
    for color in {v for row in grid for v in row if v not in (0, 5)}:
        above = sum(v == color for row in grid[:divider] for v in row)
        below = sum(v == color for row in grid[divider + 1:] for v in row)
        counts[color] = abs(above - below)
    color = max(counts, key=counts.get)
    return [[color, color], [color, color]]
